  VALUES 
    (107::BIGINT, 'Un profe super carga, las clases son muy cómicas, se esmera en que usted comprenda bien y no importa si usted no entiende, siempre que el vea que está poniendo atención el vuelve a explicarle las veces que sea. De verdad las clases son muy entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, '7826e530bb46470052af37dc182e55ec9c60c4e4d19a74c8a71f80a759ea3ffd'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Con este profe no me pudo haber quedado más claro el álgebra lineal, el curso como tal no es tan dificil y con este tipo de profes es casi imposible no pasar. Es muy vacilón, suelta comentarios cómicos durante las clases, califica suave y él sabe aclarar dudas de una forma aceptable'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'f683e8b4a2fe79e0cfb22d1a235cf1e5260d4f274de46e156e4ae36e8f044587'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, '2a847620638d1a5a5e5a7af76d58c66a35ffb0227bba0bae102ae0ef1bed83ca'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'Explica súper claro todos los temas, y los exámenes y quizzes están 100% basados en lo que se vio en clase, así que todo es justo y fácil de preparar. El curso es pesado pero con Ernesto da gusto llevar las clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd82e07b133388ff21686e4ebcaced9e4b98f4c0e2939251b0e13c90ccc5dab3d'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'No es un buen profesor, se importa muy poco porque el estudiante aprenda, explicaciones muy confusas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2024-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'b7090965d7f80166e97534fdd2a9146a529287e439a3579bc0321b894da731d8'::TEXT, ARRAY[968]::BIGINT[]),
    (107::BIGINT, 'No da mucha retroalimentación. Da por enterado los temas pasados. No hace evaluaciones. Las clases son largas. No recomiendo matricular con él.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, '6ad5ef574830750b5d8e4c61e9b44e5453c3f2b3b2cfcb89e83fb1e5e4bedc0e'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'fabcd3c3f85f97289427371eceef902bcfc8418180deabaeba7e4110b1f249dd'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Un profesor que explica muy bien y no es tan serio tampoco, parece buena persona. Si es ligeramente estricto al calificar examenes pero no tan malo con eso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2023-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3b34cc62889e5a4bc67aebfa06e2eb9f1fdf67cfd5a23b848827c530a0cdd74'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Si solo quieres pasar el curso es una buena opción. Si quieres aprender en serio, no lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'f69a65cfc883dd19c2b633150df72f73268c58a33e4bb04363ac0afdf2d245c4'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'gente, no recomiendo este profesor para discreta (en caso de virtualidad) da explicaciones muy confusas, casi no hubo retroalimentación.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-05T00:00:00+00:00'::TIMESTAMPTZ, '0f3fe98443f6ae84d090045e84c89372497431e9d0b2397c5b836a68ca5a87f6'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Explica muy bien, en general es muy buen profesor, las clases son muy interesantes y hasta divertidas a veces, en ocasiones es un poco desordenado. Sin duda alguna llevaría otro curso con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ba89da52bc84ef76d552736e8a285102fbe7c294a6bc968b561e33eb604e3a4b'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'd37cae97d40af9d92c6260ea8860c73379274703805a0b92f14065d6af7c3cee'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'El profe es bastante bueno y se ve que conoce, sin embargo se enredaba bastante en clases en algunos momentos, y también se veían ejercicios que nada que ver con lo que salía en los exámenes. Las tareas y quiz en su mayoría son bastante largos, algunos difíciles y otros fáciles.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '02f7eb9fe300f809684770ac82b5df100b4aa6aa8c325c63663ec4c1cd647e97'::TEXT, ARRAY[935]::BIGINT[]),
    (107::BIGINT, 'Es uno de los mejores profes de la escuela de mate. Si tiene el chance de matricular algo con él, no lo piense, dele. Explica suuper claro y hace mucha práctica que, generalmente, son ejercicios de exámenes pasados hechos por la cátedra. Es excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'a19799d5e5cb87b2239c84ef44729c13484d6786d7eb4d21b0257d72f8bee6ee'::TEXT, ARRAY[935]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'bb7a70c20ec18b571dc9fe372e06d1d2e8158058a6aa6edb03211839bd87554c'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Muy buen profe, en la virtualidad es un poco cansado y cuesta agarrar el hilo, pero el siempre esta dispuesto ayudar y buscar lo mejor para el estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'ba8845b7c4ab628d7199827d698cb0e92621c2e9984b6f5afd9bc09e3f0d44a1'::TEXT, ARRAY[968]::BIGINT[]),
    (107::BIGINT, 'Si es la primera vez que lleva CyA no matricule con él.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '8d3b7c1fb56d81908264cd352cd2d1a1aa157930090d4f18955c898f46167f6d'::TEXT, ARRAY[2444]::BIGINT[]),
    (107::BIGINT, 'Muy buen profesor, se preocupa por el aprendizaje del estudiante y hace que se aprenda de la fácilmente. Aunque se atrasa un poco con las notas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ce65fc5e627934094777f343da1ef67204792b970f994f8089bc871495c63f61'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Excelente profesor, de esos que inspiran al estudiante y tratan de ayudarlo de todas formas, matricular con él fue de las mejores elecciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'bd550c194a5ceb395c08c8b1c24043fb9d2fc5c0b02361e8fd00090efc59f33a'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Excelente explicando los temas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ed2480fa186fd24271d80825e08270a8c40d6850a74220ec875c787d782cd11c'::TEXT, ARRAY[1049]::BIGINT[]),
