    (107::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '45243aa4efb04ed82bb9f797013b2ecc16e92310be3e6167e2f8ccfcf77adef4'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Explica bien y el curso no es difícil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Muchos exámenes']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a0f1344252c8416e6af8f9e182df4a74e16fe01ec3f8b11ba780848eb12c6f1c'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Lo llevé en verano y fue muy fácil. El mae ayuda mucho, explica bastante bien y hace un grupo de WA para consultas. A cada rato hay examen, él recomienda hacer la práctica y el examen viene igual. Muy buena nota, hace recomendaciones semanales de música y cine, buenísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '7caa58a2aa5f64291ec8b5f468dab5fb4ab162ef2bb2a2789eed4dbbc2462b82'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'da2a1d326436697db0ab372167ab3cdd2cb1cb8d245599a113bfaf395abef52e'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Un excelente profe, se le entiende muy bien y va al grano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b302c40c46fe8b6827e5104c4a1ac64b6f02b92dffa4167f988627209bf98fd4'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '6d88b374b4d772b1aa405d4a844267c4abb99f3be8dbc4f6a8decd2248d2c806'::TEXT, ARRAY[605, 923, 2444]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'dd0ded6ae620d56c78fe9f9be8495e62e3db1d57d97f0eb16e371013756f0e78'::TEXT, ARRAY[563]::BIGINT[]),
    (107::BIGINT, 'Excelente profesor, si no le entiende algo, el mae está dispuesto a explicarle las veces que sea necesario para seguir con la clases, las clases son muy divertidas y el mae lo trata a uno como un compa. 11/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '1c176a945ce8e0f90befb1261701692216b7cbeb66deae07c7d57d4c9a20815e'::TEXT, ARRAY[563]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '35529d52dd7a690c82001c71e17d1b0e1f4b51673c106f61e9edf68d08665121'::TEXT, ARRAY[563]::BIGINT[]),
    (107::BIGINT, 'Di me culiaron pero bueno el profe, solo es que yo soy un imbecil'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '4963e5323b0dc011bf329985124ecaf4e72267ac62b2bd6a9fe852bd5386b8ba'::TEXT, ARRAY[563]::BIGINT[]),
    (107::BIGINT, 'Es un buen profe. Llevé el curso en verano y él utiliza la modalidad de hacer 5 exámenes, con esto ayuda mucho. Las clases son divertidas y explica claro la materia aunque hay que estar atento porque tiende a dar la clase un poco rápido. Sin embargo, al final del curso valora el esfuerzo de los estu'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '60c7a498fdbef3333b652e85d8071a613d98bfeff709e3c422c7ac7ddaab47fb'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Es muy buen profesor, le interesa que el estudiante aprenda y si uno muestra interés por el curso el lo ayuda. Se nota que sabe bastante y para la clase le da un folleto lleno de puros ejercicios de práctica bastante buenos. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c7f5f072077fb4d5d0ac19d38572d4d7a281789c94053769c247df741edef1cd'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Super recomendado, se le entiende super bien, califica normal, clases entretenidas y ayuda mucho al estudiante. Si puede matricular con él no lo piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'b9e7de2baec3a4089fc3a83ad3935a6ad88fce7d6b6b2adecb5c8fb8b900ff87'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Excelente profesor. Las clases son muy entretenidas y explica demasiado bien. Toda la materia se le entiende perfectamente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, 'bbd936dfac2872b6a451016e88495d21730a4a6d25418d7104440ef15145c7ba'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Es un excelente profesor, siempre hace su mayor esfuerzo para que todos entiendan; además hace la clase bastante entretenida. Es un poco desordenado pero si pones bastante atención no hay razón para perderse.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'd869c1835f11f0b5b16009ded62a8d9d8f684dd8fa818931360f871f6d937546'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Me parece un muy buen profesor, es algo desordenado, pero en general es muy gracioso y la clase se hace muy amena, yo la pasé muy bien y aprendí mucho. Puede que agarre de mono a alguien (No fue mi caso jajaja :v ) Nada más no que ser sapo xDXDxdXd'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'acb4da9c363e62e11e741f58335c8804333b455d0512a548407f1e4cae0fd32c'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'En Verano no hace examenes, solo quices y usted escoge si diarios, dia por medio o semanales. Califica suave! Y las clases son entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-04T00:00:00+00:00'::TIMESTAMPTZ, '5a60796f85eb97b2371e2ea05b5156bb547df313b970fd37eea3e1b58f0f4cfa'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Se le entiende super bien, ayuda mucho al estudiante, repite las veces que sean necesarias, califica normal, muy alegre y siempre que puede le saca una sonrisa'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd729ee1e38ecece157a0d5adab5d3bd8b5aaba678691452469284c4de34e3d19'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '02e7bcc300166fd4e2aebdb8e3b13f01a019e17bff39c61526412b73fcd12060'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Excelente profe, se preocupa mucho por que todos entiendan, califica justo y hace las clases entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2f204067c476df8266d8f0302f8ffa982b7c126b537a1472a472d06bb2e6b7df'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Explica muy bien, se le puede preguntar mil veces que él busca las mil veces explicarle para que entienda, es muy justo no regala las cosas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd5e1800355dfaedcd7c4b8ebee7e8ff9f45395dff136422d6c03a082dc34be1f'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Explica muy bien y atiende cualquier duda al momento. Las clases son entretenidas y el tiempo se pasa volando. Califica normal y es muy pasable.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0fc79e536c87101dfab58213fd0b7311e5431b75a0a7ae87eb8bbddb4f3b09ca'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'El profe es un crack, es un vegano, terrorista y pijion (broma), el mae sabe mucho y la historias que cuenta son unos viajes super raros.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5e1cacd552a45e004b1151a1d8ac9d382cd9e0050793afb0ae3b55b859c216be'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'El mejor profe que tuve de la escuela de mate. Explica demasiado bien y lo que usted necesita. Las clases son entretenidas y vacilonas.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '4260423c3319345c4dec4d27941b0eb4d768a136571e9c2bfab9cee7649afcc7'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Muy buen profe, hace la clase entretenida, y resuelve dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '32448d8096dfe89fb91af8ce95b32d4929ee153a9b640e6f7cdb4b5fa7e73e17'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'bc46c35c3c32147305d4dea8871dcba7b99a3321b8363284903df0c4a1d2df55'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'De los mejores profesores de la escuela, explica super claro, da tips muy utiles, hace la clase bastante amena, en general matriculele.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'd788ade0264ba7f34811aec86d34901d6512d0f1c0e74ff7e3ac279ddaae27e3'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Si aprendes a resolver los ejercicios como el profe lo enseña en clase, en los exámenes es solo cuestión de seguir el mismo estilo y todo irá bien. Quizzes de dificultad moderada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '47df7c7c313ea78cdd9327a4bf6c1af1d7ab0edbf9400c077be2daf68355be51'::TEXT, ARRAY[1018]::BIGINT[]),
    (107::BIGINT, 'Sinceramente malo, para cursos de enseñanza es lo peor, no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Exámenes retadores']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '34844133cd288275b9faf93901d9e1aabbbd6660523a1492aa17b77dc3493e43'::TEXT, ARRAY[1294]::BIGINT[]),
    (107::BIGINT, 'Me dio proba y creo que es el mejor profe para ese curso, lo recomiendo, ademas las clases son divertidas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ca08af9a135b4eafffccd2c24e0e4b59e3bf02cdaa5dab8f949d8de118d73c6a'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Si solo la mayoría de profesores de mate fueran tan buen profesor como Carrera. Enseña matemática como se debe: un poco de teoría junto con explicaciones y ejemplos claros en clases, esto respaldado por muchos ejercicios para la casa. Hace que uno realmente domine la materia, aunque sea complicado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'b024ed78d66d65da8385e60ac4865f76cb65c37f932f543751f5c3210b5b0070'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Excelente profe, se preocupa porque el estudiante entienda toda la materia, es buena gente le podes preguntar cualquier duda las veces que sean necesarias. Los exámenes son relativamente sencillos si uno se estudia la practica de fijo te va bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, '92f7f29f71d4fa837e89735d393031c2564335162dadb6bd83ba389795433903'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'De los mejores profesores con los que he tenido el gusto de matricular, explica super bien, se preocupa por que el estudiante aprenda lo necesario y es una teja de persona, inclusive hace que las clases no sean aburridas. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'b28e7942183c291b935a89d5f8f4920022a4e5ed98d2edda79572225ddfad1ba'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'El profe es muy pura vida, se le entiende, siempre trata de ayudar. Califica normal, hace que las clases sean divertidas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f8dbca4264acad82066fba706e70944e6a3751e9eb12139e74c47f71ef2fda29'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Es un excelente profesor, ayuda mucho a los estudiantes y se interesa porque uno aprenda. Es uno de los mejores profesores de la Escuela de Matemática.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4adf0e0aa618189a6b130128ba5a333c928be0907450f3458efba75fbe801879'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Es demasiado bueno, explica muy bien, es muy pura vida, las clases son entretenidas, califica normal, y si tiene que repetir lo hace sin ningún problema. En mi opinión es uno de los mejores profes del TEC'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'e6a664f5981031725c7842dd4fee41d7583629ea8a8e4cda64100f09b318eccf'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'Muy buen profesor, lo lleve en verano, las clases son un exito porque no son aburridas, explica muy bien. Califica mas o menos, yo diria que justo. Las clases son divertidas, y valen la pena.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-11T00:00:00+00:00'::TIMESTAMPTZ, '902675242f3e4e25a77699f9c4db80c2403a7e0c23d05894e0c474f42ab04d00'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Tiene bien puesto el titulo de profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-05T00:00:00+00:00'::TIMESTAMPTZ, '578cdf1c3a1bf84f1e75e3804fd4ea9b8719df648daa4226b5270d69960483b9'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Excelente profe, rarísimo, excéntrico, sarcástico, amigable, divertido...un compa dando clase. Totalmente recomendado para todo. Salvo para Superior, porque no sabe dibujar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'fb4e78ec892675c5ce196481e2d1c297e69a63566a691f4e58c54856a4f9ae65'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Muy buen profe, explica con muchas ganas y no le importa repetir la explicación varias veces.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, '599b7b68a22ba7e65e62095615297275239e1ec28e570f9745b35681241811fc'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Demasiado buena nota, revisa muy justo...además explica con muchas ganas (tiene vocacion) y muy bien... Hace la clase muy llevadera y entretenida, y es muy vacilon... Recomendado al 100 porciento si quiere aprender, no estar tan estresado con la materia, y pasar!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '924f8f34237e3039d16b45ba69cb92110bae3df51dd6ed9baea61d44d49c3423'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Excelente profesor, se esmera por dejar la materia clara y las clases son bastante entretenidas. Totalmente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '2f30c78947c81032af53dde4681e6da3a2d0a6c725d21b114f51d1e40f1986bb'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Mejor profe que existe, aveces se pasa de habla paja jajaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-06T00:00:00+00:00'::TIMESTAMPTZ, 'eb60d520583076f6031a200fb6aa5f76551f4628c52414d454874b87271e4399'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, '528d71be2d15e1c854cc771450190c4d160987719fd272dba4e4ffc337673a88'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'El profe es muy pura vida, las clases las hace entretenidas y explica muy bien, deja todo muy claro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '80dc0a5238243f06210c81fc0bcfbfcda1baed7642069ef8f80ff17e2e956ae2'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Excelente profesor, es una teja de persona y cuando se le agarra el toque explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0d159f641f06a8ed89e6ff3ef4831bcd59f4e21e6dbfddc10430383a24a2b563'::TEXT, ARRAY[605]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '1528b5506274f49faffe0fc083755add59a260359acef34bfb027ab05ffa30e4'::TEXT, ARRAY[935]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3fa04f3ae75eae00987ca4cf1709d3da4e9b528785a5d7562751b1d0abcfa6a6'::TEXT, ARRAY[634]::BIGINT[]),
    (107::BIGINT, 'Explica muy bien, las clases no aburren y es pura vida'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '453ddddec3643fdffd7e38fa6f5976cf980abb0f7eecbf4d7f2f0f12c5918bcb'::TEXT, ARRAY[1049]::BIGINT[]),
    (107::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e686740802b49583ae6d13996fb16f9881ad175329da49ed03710ac09740a584'::TEXT, ARRAY[935]::BIGINT[]),
    (107::BIGINT, 'Sus clases nunca aburren, es una teja.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5ef44421c0b23ab6bf350b07f8eb6f50816a77028365b07b22f65c762257c02d'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
